type UserDAO interface {
    Find(ctx context.Context, id int64) (*User, error)
}

func NewUserDAO(db *sql.DB, store string) (UserDAO, error) {
    switch store {
    case "postgres":
        return &pgUserDAO{db: db}, nil     // dialect lives in the impl
    case "sqlite":
        return &sqliteUserDAO{db: db}, nil
    default:
        return nil, fmt.Errorf("unsupported store %q", store)
    }
}

